//! Quality snapshot for morph, generated by sdsp-test-kit.
//!
//! Fixed probes through the real CLAP plugin (default params: Source = Model,
//! Bashkir Kubyz, Morph 0.8), recorded to `tests/quality.snap`:
//!
//!     SDSP_UPDATE_SNAPSHOTS=1 cargo test -p superduper-morph --test quality

use clack_common::events::{event_types::ParamValueEvent, Pckn};
use clack_common::utils::{ClapId, Cookie};
use sdsp_test_kit::probes::{self, db};
use sdsp_test_kit::{render_effect, PluginUnderTest, Suite};
use superduper_morph::engine::LATENCY;

struct Target;
impl PluginUnderTest for Target {
    type Plugin = superduper_morph::SuperDuperMorph;
    const ID: &'static std::ffi::CStr = c"co.superduperai.morph";
}

const SR: f64 = 48_000.0;

#[test]
fn quality_snapshot() {
    let mut s = Suite::new("morph", concat!(env!("CARGO_MANIFEST_DIR"), "/tests/quality.snap")).default_tolerance(1.0);
    let frames = 1 << 15;

    let tone = probes::tone(SR as f32, 1000.0, 0.5, frames);
    let (out, _) = render_effect::<Target>(SR, &tone, &tone);
    s.record("tone_gain_db", probes::gain_db(&tone, &out));
    s.record("tone_peak_db", db(probes::peak(&out)));
    for (band, level) in probes::band_shape(&out, SR as f32) {
        s.record(format!("tone_band_{band}"), level);
    }

    let voice = sdsp_test_kit::signals::voiced(frames as f32 / SR as f32);
    let (vout, _) = render_effect::<Target>(SR, &voice, &voice);
    s.record("voice_gain_db", probes::gain_db(&voice, &vout));
    s.record("voice_max_step", probes::max_step(&vout));
    for (band, level) in probes::band_shape(&vout, SR as f32) {
        s.record(format!("voice_band_{band}"), level);
    }

    let noise = probes::noise(frames, 0.3);
    let (nout, _) = render_effect::<Target>(SR, &noise, &noise);
    s.record("noise_gain_db", probes::gain_db(&noise, &nout));
    for (band, level) in probes::band_shape(&nout, SR as f32) {
        s.record(format!("noise_band_{band}"), level);
    }

    let imp = probes::impulse(frames);
    let (iout, _) = render_effect::<Target>(SR, &imp, &imp);
    s.record("impulse_rms_db", db(probes::rms(&iout)));

    sdsp_test_kit::params::record_table(&mut s, superduper_morph::PARAMS);
    s.finish();
}

#[test]
fn morph_zero_through_the_host_is_the_delayed_dry() {
    let x = sdsp_test_kit::signals::voiced(1.0);
    let id = ClapId::new(superduper_morph::P_MORPH as u32);
    let (l, r) = sdsp_test_kit::host::render_with::<Target>(SR, 512, &x, &x, move |pos, buf| {
        if pos == 0 {
            buf.push(&ParamValueEvent::new(0, id, Pckn::match_all(), 0.0, Cookie::empty()));
        }
    });
    let n = l.len() / 512 * 512; // the kit renders whole blocks only
    let err = (LATENCY..n).map(|i| (l[i] - x[i - LATENCY]).abs().max((r[i] - x[i - LATENCY]).abs())).fold(0.0f32, f32::max);
    let peak = x.iter().fold(0.0f32, |m, v| m.max(v.abs()));
    let db = 20.0 * (err.max(1e-12) / peak).log10();
    assert!(db < -90.0, "Morph 0 differs from the {LATENCY}-sample delayed input by {db:.1} dB");
}

#[test]
fn parameter_table_is_consistent() {
    sdsp_test_kit::params::check_table("superduper-morph", superduper_morph::PARAMS, superduper_morph::STEPPED_PARAMS);
}

#[global_allocator]
static ALLOC: sdsp_test_kit::alloc::CountingAllocator = sdsp_test_kit::alloc::CountingAllocator;

#[test]
fn process_does_not_allocate() {
    let frames = 1 << 14;
    let voice = sdsp_test_kit::signals::voiced(frames as f32 / SR as f32);
    sdsp_test_kit::alloc::reset();
    let _ = render_effect::<Target>(SR, &voice, &voice);
    sdsp_test_kit::alloc::assert_rt_clean("superduper-morph", frames / 512);
}
